-- create "monetisation_holds" table
CREATE TABLE "monetisation_holds" ("id" character varying NOT NULL, "is_paused" boolean NOT NULL DEFAULT false, "account_status" character varying NOT NULL DEFAULT 'GOOD_STANDING', "restrictions" jsonb NOT NULL DEFAULT '[]'::jsonb, "reason" character varying NOT NULL DEFAULT '', "health_changed_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
